#include <iostream>
using namespace std;

int n, sum = 0;

void dfs(int x) {
    if (x <= n)
        sum++;
    else
        return;

    dfs(x * 10 + 7);
    dfs(x * 10 + 4);
}

int main() {
    cin >> n;
    dfs(4);
    dfs(7);
    cout << sum;
    return 0;
}

